{
  "name": "browserbench",
  "version": "0.1.0",
  "license": "MIT",
  "engines": {
    "node": ">=18"
  },
  "description": "remote browser benchmark",
  "main": "index.js",
  "scripts": {
    "dev": "tsx src/cli.ts",
    "build": "tsc -p tsconfig.json",
    "bench": "node dist/cli.js",
    "sumamrize": "tsx scripts/summarize.ts"
  },
  "author": "junhsss <junhsssr@gmail.com>",
  "devDependencies": {
    "@types/node": "^24.10.0",
    "tsx": "^4.20.6",
    "typescript": "^5.9.3"
  },
  "dependencies": {
    "@browserbasehq/sdk": "^2.6.0",
    "anchorbrowser": "^0.8.3",
    "steel-sdk": "^0.14.0",
    "@hyperbrowser/sdk": "^0.71.0",
    "@onkernel/sdk": "^0.18.0",
    "dotenv": "^17.2.3",
    "playwright-core": "^1.56.1"
  }
}

import type { ProviderClient, ProviderSession } from "../types.js";
import { requireEnv } from "../utils/env.js";
import { Browserbase } from "@browserbasehq/sdk";

export class BrowserbaseProvider implements ProviderClient {
  readonly name = "BROWSERBASE";
  private _client: Browserbase | null = null;

  private async client(): Promise<Browserbase | null> {
    if (!this._client) {
      const apiKey = requireEnv("BROWSERBASE_API_KEY");
      this._client = new Browserbase({ apiKey });
    }
    return this._client;
  }

  async create(): Promise<ProviderSession> {
    const projectId = requireEnv("BROWSERBASE_PROJECT_ID");
    const session = await (await this.client())?.sessions.create({ projectId });
    const id = session?.id;
    const cdpUrl = session?.connectUrl;
    if (!id || !cdpUrl) throw new Error("Invalid Browserbase session response");
    return { id, cdpUrl };
  }

  async release(id: string): Promise<void> {
    const projectId = requireEnv("BROWSERBASE_PROJECT_ID");
    await (
      await this.client()
    )?.sessions.update(id, { status: "REQUEST_RELEASE", projectId });
  }
}

import type { ProviderClient, ProviderSession } from "../types.js";
import { requireEnv } from "../utils/env.js";
import { Hyperbrowser } from "@hyperbrowser/sdk";

export class HyperbrowserProvider implements ProviderClient {
  readonly name = "HYPERBROWSER";
  private _client: Hyperbrowser | null = null;

  private async client(): Promise<Hyperbrowser> {
    if (!this._client) {
      const apiKey = requireEnv("HYPERBROWSER_API_KEY");
      this._client = new Hyperbrowser({ apiKey });
    }
    return this._client;
  }

  async create(): Promise<ProviderSession> {
    const session = await (await this.client()).sessions.create();
    const id = session.id;
    const cdpUrl = session.wsEndpoint;
    if (!id || !cdpUrl)
      throw new Error("Invalid Hyperbrowser session response");
    return { id, cdpUrl };
  }

  async release(id: string): Promise<void> {
    await (await this.client()).sessions.stop(id);
  }
}

import type { ProviderClient, ProviderSession } from "../types.js";
import Anchorbrowser from "anchorbrowser";
import { requireEnv } from "../utils/env.js";

export class AnchorBrowserProvider implements ProviderClient {
  readonly name = "ANCHORBROWSER";
  private _client: Anchorbrowser | null = null;

  private async client(): Promise<Anchorbrowser> {
    if (!this._client) {
      const apiKey = requireEnv("ANCHORBROWSER_API_KEY");
      this._client = new Anchorbrowser({ apiKey });
    }
    return this._client;
  }

  async create(): Promise<ProviderSession> {
    const session = await (await this.client()).sessions.create();
    const id = session.data?.id;
    const cdpUrl = session.data?.cdp_url;
    if (!id || !cdpUrl)
      throw new Error("Invalid Anchorbrowser session response");
    return { id, cdpUrl };
  }

  async release(id: string): Promise<void> {
    await (await this.client()).sessions.delete(id);
  }
}

