import "dotenv/config";
import fs from "node:fs";
import { resolveProvider } from "./providers/index.js";
import { runLoop } from "./run.js";
import { getArg } from "./utils/arg.js";

async function main() {
  const providerArg = getArg(
    "provider",
    process.env.PROVIDER || "browserbase"
  )!;
  const runs = Number(getArg("runs", process.env.RUNS || "5"));
  const url = getArg("url", process.env.URL || "https://google.com/")!;
  const outArg = getArg("out", process.env.OUTPUT || undefined);
  const rateArg = getArg("rate", process.env.RATE || undefined);
  const rate = rateArg ? Number(rateArg) : undefined; // sessions per minute

  const providerNames = providerArg
    .split(",")
    .map((p) => p.trim())
    .filter(Boolean);

  for (const providerName of providerNames) {
    const provider = resolveProvider(providerName);
    const out = outArg || `results/${providerName}.jsonl`;

    // Nuke existing file before starting
    if (fs.existsSync(out)) {
      fs.unlinkSync(out);
      console.error(`[RESET] Deleted existing ${out}`);
    }

    await runLoop(provider, { runs, url, out, rate });
  }
}

main()
  .then(() => {
    process.exit(0);
  })
  .catch((e) => {
    console.error(`[FATAL] ${e?.stack || e?.message || e}`);
    process.exit(1);
  });

export type ProviderName =
  | "STEEL"
  | "BROWSERBASE"
  | "ANCHORBROWSER"
  | "HYPERBROWSER"
  | "KERNEL";

export type MetricRecord = {
  created_at: string;
  id: string | null;
  session_creation_ms: number | null;
  session_connect_ms: number | null;
  page_goto_ms: number | null;
  session_release_ms: number | null;
  provider: ProviderName;
  success: boolean;
  error_stage: string | null;
  error_message: string | null;
};

export type ProviderSession = {
  id: string;
  cdpUrl: string;
};

export interface ProviderClient {
  readonly name: ProviderName;
  create(): Promise<ProviderSession>;
  release(id: string): Promise<void>;
}

import fs from "node:fs";
import { chromium, type Browser } from "playwright-core";
import type { MetricRecord, ProviderClient } from "./types.js";
import { isoUtcNow, nowNs, msSince } from "./utils/time.js";

export async function runSingleSession(
  provider: ProviderClient,
  url: string
): Promise<MetricRecord> {
  let browser: Browser | null = null;
  let session: { id: string } | null = null;
  let stage = "init";

  const result: MetricRecord = {
    created_at: isoUtcNow(),
    id: null,
    session_creation_ms: null,
    session_connect_ms: null,
    page_goto_ms: null,
    session_release_ms: null,
    provider: provider.name,
    success: false,
    error_stage: null,
    error_message: null,
  };

  try {
    stage = "session_create";
    let id: string;
    let cdpUrl: string;

    if (provider.name === "KERNEL") {
      while (true) {
        try {
          const t0 = nowNs();
          const created = await provider.create();
          ({ id, cdpUrl } = created);
          result.id = id;
          session = { id };
          result.session_creation_ms = msSince(t0);
          console.error(
            `[Session created] provider=${provider.name} id=${id} ${result.session_creation_ms}ms`
          );
          break;
        } catch (e: any) {
          const status = e?.status ?? e?.statusCode ?? e?.response?.status;
          const message = e instanceof Error ? e.message : `${e}`;
          const isRateLimit =
            status === 429 || /rate|limit|429|too many/i.test(message || "");
          if (isRateLimit) {
            console.error(
              `[RATE_LIMIT] provider=KERNEL message="${message}" → retry in 30s`
            );
            await new Promise((r) => setTimeout(r, 30_000));
            continue;
          }
          throw e;
        }
      }
    } else {
      const t0 = nowNs();
      const created = await provider.create();
      ({ id, cdpUrl } = created);
      result.id = id;
      session = { id };
      result.session_creation_ms = msSince(t0);
      console.error(
        `[Session created] provider=${provider.name} id=${id} ${result.session_creation_ms}ms`
      );
    }

    stage = "connect_over_cdp";
    const t1 = nowNs();
    browser = await chromium.connectOverCDP(cdpUrl);
    result.session_connect_ms = msSince(t1);
    console.error(`[Browser connected] ${result.session_connect_ms}ms`);

    stage = "page_goto";
    const t2 = nowNs();
    const context = browser.contexts()[0] || (await browser.newContext());
    const page = context.pages()[0] || (await context.newPage());
    await page.goto(url, { waitUntil: "domcontentloaded" });
    result.page_goto_ms = msSince(t2);
    console.error(`[Page visited] ${result.page_goto_ms}ms`);

    result.success = true;
  } catch (e: any) {
    const message = e instanceof Error ? e.stack || e.message : `${e}`;
    result.error_stage = stage;
    result.error_message = message;
    console.error(`[ERROR] stage=${stage} id=${result.id} ${message}`);
  } finally {
    if (session?.id) {
      try {
        stage = "session_release";
        const t3 = nowNs();
        await provider.release(session.id);
        result.session_release_ms = msSince(t3);
        console.error(`[Session released] ${result.session_release_ms}ms`);
      } catch (e: any) {
        console.error(
          `[SESSION_RELEASE_ERROR] id=${session.id} ${e?.message || e}`
        );
      }
    }

    // Avoid rate limit for Browserbase
    if (provider.name === "BROWSERBASE") {
      await new Promise((resolve) =>
        setTimeout(
          resolve,
          Math.max(
            3000 -
              ((result.session_creation_ms ?? 0) +
                (result.session_connect_ms ?? 0) +
                (result.page_goto_ms ?? 0) +
                (result.session_release_ms ?? 0))
          ),
          0
        )
      );
    }
  }

  return result;
}

const WARMUP_RUNS = 10;

export async function runLoop(
  provider: ProviderClient,
  { runs, url, out, rate }: { runs: number; url: string; out: string; rate?: number }
) {
  const minIntervalMs = rate ? (60 / rate) * 1000 : 0; // minimum ms between sessions

  if (rate) {
    console.error(`[RATE_LIMIT] Throttling to ${rate} sessions/min (${(minIntervalMs / 1000).toFixed(1)}s interval)`);
  }

  for (let i = 1; i <= WARMUP_RUNS; i++) {
    const start = Date.now();
    console.error(`[WARMUP] ${i}/${WARMUP_RUNS}`);
    await runSingleSession(provider, url);
    await throttle(start, minIntervalMs);
  }

  let success = 0;
  let failure = 0;

  for (let i = 1; i <= runs; i++) {
    const start = Date.now();
    console.error(`[RUN] ${i}/${runs}`);
    const record = await runSingleSession(provider, url);
    fs.appendFileSync(out, JSON.stringify(record) + "\n", {
      encoding: "utf-8",
    });
    if (record.success) success++;
    else failure++;
    await throttle(start, minIntervalMs);
  }
  console.error(`Success: ${success}, Failure: ${failure}`);
}

async function throttle(startTime: number, minIntervalMs: number): Promise<void> {
  if (minIntervalMs <= 0) return;
  const elapsed = Date.now() - startTime;
  const remaining = minIntervalMs - elapsed;
  if (remaining > 0) {
    await new Promise((r) => setTimeout(r, remaining));
  }
}

import "dotenv/config";

export function requireEnv(name: string): string {
  const v = process.env[name];
  if (!v) throw new Error(`${name} is not set`);
  return v;
}

import type { ProviderClient, ProviderSession } from "../types.js";
import { requireEnv } from "../utils/env.js";
import Steel from "steel-sdk";

export class SteelProvider implements ProviderClient {
  readonly name = "STEEL";
  private _client: Steel | null = null;

  private async client(): Promise<Steel> {
    if (!this._client) {
      const apiKey = requireEnv("STEEL_API_KEY");
      this._client = new Steel({ steelAPIKey: apiKey });
    }
    return this._client;
  }

  async create(): Promise<ProviderSession> {
    const apiKey = requireEnv("STEEL_API_KEY");
    const session = await (await this.client()).sessions.create();
    const id = session?.id;
    const websocketUrl = session?.websocketUrl;
    const cdpUrl = `${websocketUrl}&apiKey=${apiKey}`;
    if (!id || !cdpUrl) throw new Error("Invalid Steel session response");
    return { id, cdpUrl };
  }

  async release(id: string): Promise<void> {
    await (await this.client()).sessions.release(id);
  }
}

export function getArg(name: string, fallback?: string) {
  const argv = process.argv.slice(2);

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];

    if (!token.startsWith("--")) continue;

    if (token.startsWith(`--${name}=`)) {
      const value = token.slice(name.length + 3);
      return value !== "" ? value : fallback;
    }

    if (token === `--${name}`) {
      const next = argv[i + 1];
      if (next && !next.startsWith("-")) return next;
      return fallback;
    }
  }

  return fallback;
}

export const isoUtcNow = () => new Date().toISOString();
export const nowNs = () => process.hrtime.bigint();
export const msSince = (start: bigint) =>
  Number((process.hrtime.bigint() - start) / 1_000_000n);

import type { ProviderClient } from "../types.js";
import { BrowserbaseProvider } from "./browserbase.js";
import { SteelProvider } from "./steel.js";
import { AnchorBrowserProvider } from "./anchorbrowser.js";
import { HyperbrowserProvider } from "./hyperbrowser.js";
import { KernelProvider } from "./kernel.js";

export function resolveProvider(name: string): ProviderClient {
  const key = name.trim().toLowerCase();

  if (key === "browserbase" || key === "bb") return new BrowserbaseProvider();
  if (key === "steel") return new SteelProvider();
  if (key === "anchorbrowser" || key === "anchor")
    return new AnchorBrowserProvider();
  if (key === "hyperbrowser" || key === "hyper")
    return new HyperbrowserProvider();
  if (key === "kernel") return new KernelProvider();
  throw new Error(`Unknown provider: ${name}`);
}

import type { ProviderClient, ProviderSession } from "../types.js";
import { requireEnv } from "../utils/env.js";
import Kernel from "@onkernel/sdk";

export class KernelProvider implements ProviderClient {
  readonly name = "KERNEL";
  private _client: Kernel | null = null;

  private async client(): Promise<Kernel> {
    if (!this._client) {
      const apiKey = requireEnv("KERNEL_API_KEY");
      this._client = new Kernel({ apiKey });
    }
    return this._client;
  }

  async create(): Promise<ProviderSession> {
    const created = await (await this.client()).browsers.create();
    const id = created.session_id;
    const cdpUrl = created.cdp_ws_url;
    if (!id || !cdpUrl) throw new Error("Invalid Kernel session response");
    return { id, cdpUrl };
  }

  async release(id: string): Promise<void> {
    await (await this.client()).browsers.deleteByID(id);
  }
}
